'use strict';

/**
 * SQLite access layer.
 *
 * Every statement is prepared once and executed with bound parameters. No SQL string in this
 * file is built by concatenating a value into it — the search term below is the obvious place
 * that would go wrong, and it is bound like everything else.
 */

const Database = require('better-sqlite3');

const db = new Database(process.env.DATABASE_FILE || ':memory:');

db.exec(`
  CREATE TABLE IF NOT EXISTS products (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    name        TEXT    NOT NULL,
    description TEXT    NOT NULL DEFAULT '',
    price_cents INTEGER NOT NULL,
    updated_at  TEXT    NOT NULL DEFAULT (datetime('now'))
  );
  CREATE INDEX IF NOT EXISTS products_name_idx ON products (name);
`);

// Prepared once, bound per call. `?` placeholders, never interpolation.
const statements = {
  search: db.prepare(
    'SELECT id, name, description, price_cents FROM products ' +
    'WHERE name LIKE ? OR description LIKE ? ORDER BY name LIMIT ?'
  ),
  byId: db.prepare('SELECT id, name, description, price_cents FROM products WHERE id = ?'),
  insert: db.prepare(
    'INSERT INTO products (name, description, price_cents) VALUES (?, ?, ?)'
  ),
  update: db.prepare(
    'UPDATE products SET name = ?, description = ?, price_cents = ?, ' +
    "updated_at = datetime('now') WHERE id = ?"
  ),
};

function searchProducts(term, limit = 25) {
  // The wildcards are added to the *value*, not to the SQL, so the term stays a bound parameter.
  const pattern = '%' + term + '%';
  return statements.search.all(pattern, pattern, limit);
}

function getProduct(id) {
  return statements.byId.get(id);
}

function createProduct({ name, description, priceCents }) {
  const result = statements.insert.run(name, description, priceCents);
  return getProduct(result.lastInsertRowid);
}

function updateProduct(id, { name, description, priceCents }) {
  const result = statements.update.run(name, description, priceCents, id);
  return result.changes === 0 ? undefined : getProduct(id);
}

module.exports = { db, searchProducts, getProduct, createProduct, updateProduct };

