'use strict';

/**
 * Application entrypoint.
 *
 * Security middleware is registered here, before any route, so nothing can be served without
 * passing through it:
 *
 *   helmet          strict HTTP security headers (CSP, HSTS, nosniff, frameguard)
 *   cors            an explicit origin allow-list, not a wildcard
 *   express-rate-limit  a per-IP request budget on the API surface
 *   express.json    a body size cap, so a large body is rejected before it is parsed
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const routes = require('./routes');

const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000')
  .split(',')
  .map((origin) => origin.trim())
  .filter(Boolean);

function createApp() {
  const app = express();

  app.use(
    helmet({
      contentSecurityPolicy: {
        directives: {
          defaultSrc: ["'self'"],
          scriptSrc: ["'self'"],
          styleSrc: ["'self'", "'unsafe-inline'"],
          objectSrc: ["'none'"],
          frameAncestors: ["'none'"],
        },
      },
      hsts: { maxAge: 31536000, includeSubDomains: true },
      referrerPolicy: { policy: 'no-referrer' },
    })
  );

  // Strict: an origin not on the list is refused rather than reflected back.
  app.use(
    cors({
      origin(origin, callback) {
        if (!origin || ALLOWED_ORIGINS.includes(origin)) return callback(null, true);
        return callback(new Error('origin not allowed'));
      },
      methods: ['GET', 'POST', 'PUT'],
      maxAge: 600,
    })
  );

  app.use(express.json({ limit: '32kb' }));

  app.use(
    '/api',
    rateLimit({
      windowMs: 60 * 1000,
      max: 60,
      standardHeaders: true,
      legacyHeaders: false,
      message: { error: 'too many requests' },
    })
  );

  app.use(express.static('public'));
  app.use('/api', routes);

  app.use((err, _req, res, _next) => {
    if (err && err.message === 'origin not allowed') return res.status(403).json({ error: 'forbidden' });
    if (err && err.type === 'entity.too.large') return res.status(413).json({ error: 'body too large' });
    return res.status(500).json({ error: 'internal error' });
  });

  return app;
}

if (require.main === module) {
  const port = Number(process.env.PORT || 3000);
  createApp().listen(port, () => console.log('listening on ' + port));
}

module.exports = { createApp, ALLOWED_ORIGINS };

