'use strict';

/**
 * Cache-aside service.
 *
 * Every read path goes through getOrSet(): look in the cache, and only on a miss call the
 * loader and store what it returns. Nothing else in the app talks to the cache directly, so
 * there is exactly one place where keys are built and exactly one place where entries expire.
 *
 * Writes never update the cache in place. They invalidate, and the next read repopulates.
 * In-place updates are how a cache and its database drift apart: a failed write leaves a
 * cache entry claiming the write succeeded.
 */

// TTLs in seconds. Search results churn as the catalogue changes; a single product changes
// rarely, so it is held roughly ten times longer.
const TTL_SECONDS = {
  SEARCH: 30,
  PRODUCT: 300,
};

const NAMESPACE = 'products';

const store = new Map();

/** Namespaced, so a flush of this feature cannot evict another feature's entries. */
function keyFor(kind, value) {
  const normalised = String(value == null ? '' : value).trim().toLowerCase();
  return NAMESPACE + ':' + kind + ':' + normalised;
}

function get(key) {
  const entry = store.get(key);
  if (!entry) return undefined;
  if (entry.expiresAt <= Date.now()) {
    store.delete(key);
    return undefined;
  }
  return entry.value;
}

function set(key, value, ttlSeconds) {
  store.set(key, { value, expiresAt: Date.now() + ttlSeconds * 1000 });
  return value;
}

/** The cache-aside read path: hit returns immediately, miss loads and stores. */
function getOrSet(key, ttlSeconds, loader) {
  const hit = get(key);
  if (hit !== undefined) {
    stats.hits += 1;
    return hit;
  }
  stats.misses += 1;
  return set(key, loader(), ttlSeconds);
}

/**
 * Explicit invalidation, called by every write endpoint.
 *
 * The product's own key is dropped by name. Every search key is dropped as well, because a
 * new or edited product can appear in or vanish from any query, and there is no way to know
 * which cached result sets it belongs to without running them again.
 */
function invalidateProduct(id) {
  store.delete(keyFor('id', id));
  let dropped = 1;
  for (const key of Array.from(store.keys())) {
    if (key.startsWith(NAMESPACE + ':search:')) {
      store.delete(key);
      dropped += 1;
    }
  }
  return dropped;
}

const stats = { hits: 0, misses: 0 };

function reset() {
  store.clear();
  stats.hits = 0;
  stats.misses = 0;
}

module.exports = { TTL_SECONDS, NAMESPACE, keyFor, get, set, getOrSet, invalidateProduct, stats, reset };

