'use strict';

/**
 * Product routes.
 *
 * Reads go through the cache-aside service. Writes validate, hit the database, then explicitly
 * invalidate — in that order, so a rejected write never evicts anything.
 */

const express = require('express');
const cache = require('./cache');
const db = require('./db');
const { productBody, searchQuery, idParam, validate } = require('./schemas');

const router = express.Router();

router.get('/products', (req, res) => {
  const parsed = validate(searchQuery, req.query);
  if (!parsed.ok) return res.status(400).json({ errors: parsed.errors });

  const { q, limit } = parsed.data;
  const key = cache.keyFor('search', q + '|' + limit);
  const before = cache.stats.hits;
  const results = cache.getOrSet(key, cache.TTL_SECONDS.SEARCH, () => db.searchProducts(q, limit));

  res.set('X-Cache', cache.stats.hits > before ? 'HIT' : 'MISS');
  res.json({ results });
});

router.get('/products/:id', (req, res) => {
  const parsed = idParam.safeParse(req.params.id);
  if (!parsed.success) return res.status(400).json({ errors: [{ path: 'id', message: 'invalid id' }] });

  const id = parsed.data;
  const key = cache.keyFor('id', id);
  const before = cache.stats.hits;
  const product = cache.getOrSet(key, cache.TTL_SECONDS.PRODUCT, () => db.getProduct(id) || null);

  if (!product) return res.status(404).json({ error: 'not found' });
  res.set('X-Cache', cache.stats.hits > before ? 'HIT' : 'MISS');
  res.json(product);
});

router.post('/products', (req, res) => {
  const parsed = validate(productBody, req.body);
  if (!parsed.ok) return res.status(400).json({ errors: parsed.errors });

  const product = db.createProduct(parsed.data);
  // A new product can match existing searches, so every search key goes.
  cache.invalidateProduct(product.id);
  res.status(201).json(product);
});

router.put('/products/:id', (req, res) => {
  const id = idParam.safeParse(req.params.id);
  if (!id.success) return res.status(400).json({ errors: [{ path: 'id', message: 'invalid id' }] });

  const parsed = validate(productBody, req.body);
  if (!parsed.ok) return res.status(400).json({ errors: parsed.errors });

  const product = db.updateProduct(id.data, parsed.data);
  if (!product) return res.status(404).json({ error: 'not found' });

  cache.invalidateProduct(id.data);
  res.json(product);
});

module.exports = router;

