'use strict';

/**
 * Request validation schemas.
 *
 * Every POST and PUT body is parsed through one of these before it reaches the database layer.
 * Validation is strict: unknown keys are rejected rather than ignored, so a client cannot smuggle
 * a field the handler does not expect.
 */

const { z } = require('zod');

const productBody = z
  .object({
    name: z.string().trim().min(1, 'name is required').max(120),
    description: z.string().trim().max(2000).default(''),
    priceCents: z.number().int().nonnegative().max(100000000),
  })
  .strict();

const searchQuery = z
  .object({
    q: z.string().trim().min(1).max(80),
    limit: z.coerce.number().int().positive().max(100).default(25),
  })
  .strict();

const idParam = z.coerce.number().int().positive();

/** Returns { ok: true, data } or { ok: false, errors } — never throws at the caller. */
function validate(schema, value) {
  const result = schema.safeParse(value);
  if (result.success) return { ok: true, data: result.data };
  return {
    ok: false,
    errors: result.error.issues.map((issue) => ({
      path: issue.path.join('.'),
      message: issue.message,
    })),
  };
}

module.exports = { productBody, searchQuery, idParam, validate };

