'use strict';

/** Unit tests for the cache service: key generation, TTL expiry, and invalidation. */

const assert = require('node:assert/strict');
const { test, beforeEach } = require('node:test');
const cache = require('../../cache');

beforeEach(() => cache.reset());

test('keys are namespaced and normalised', () => {
  assert.equal(cache.keyFor('id', 7), 'products:id:7');
  assert.equal(cache.keyFor('search', '  Widget  '), 'products:search:widget');
  // Case and surrounding whitespace must not produce two entries for one query.
  assert.equal(cache.keyFor('search', 'WIDGET'), cache.keyFor('search', 'widget'));
});

test('keys for different kinds never collide', () => {
  assert.notEqual(cache.keyFor('id', 'x'), cache.keyFor('search', 'x'));
});

test('a null or undefined value still produces a usable key', () => {
  assert.equal(cache.keyFor('id', null), 'products:id:');
  assert.equal(cache.keyFor('id', undefined), 'products:id:');
});

test('getOrSet calls the loader once, then serves from the cache', () => {
  let calls = 0;
  const loader = () => { calls += 1; return { value: calls }; };

  const first = cache.getOrSet('k', 60, loader);
  const second = cache.getOrSet('k', 60, loader);

  assert.equal(calls, 1, 'the second read must not reach the loader');
  assert.deepEqual(first, second);
  assert.equal(cache.stats.misses, 1);
  assert.equal(cache.stats.hits, 1);
});

test('an entry past its TTL is a miss and is reloaded', () => {
  cache.set('k', 'stale', -1); // already expired
  const value = cache.getOrSet('k', 60, () => 'fresh');
  assert.equal(value, 'fresh');
});

test('TTL constants are defined, and a product outlives a search result', () => {
  assert.ok(cache.TTL_SECONDS.SEARCH > 0);
  assert.ok(cache.TTL_SECONDS.PRODUCT > cache.TTL_SECONDS.SEARCH);
});

test('invalidating a product drops its key and every search key', () => {
  cache.set(cache.keyFor('id', 1), 'product one', 60);
  cache.set(cache.keyFor('search', 'widget'), ['a'], 60);
  cache.set(cache.keyFor('search', 'gadget'), ['b'], 60);

  cache.invalidateProduct(1);

  assert.equal(cache.get(cache.keyFor('id', 1)), undefined);
  assert.equal(cache.get(cache.keyFor('search', 'widget')), undefined);
  assert.equal(cache.get(cache.keyFor('search', 'gadget')), undefined);
});

test('invalidating one product leaves another product cached', () => {
  cache.set(cache.keyFor('id', 1), 'one', 60);
  cache.set(cache.keyFor('id', 2), 'two', 60);

  cache.invalidateProduct(1);

  assert.equal(cache.get(cache.keyFor('id', 1)), undefined);
  assert.equal(cache.get(cache.keyFor('id', 2)), 'two');
});

