'use strict';

/** Unit tests for the request validation schemas. */

const assert = require('node:assert/strict');
const { test } = require('node:test');
const { productBody, searchQuery, idParam, validate } = require('../../schemas');

test('a well-formed product body is accepted and trimmed', () => {
  const result = validate(productBody, { name: '  Widget  ', description: 'A thing', priceCents: 1250 });
  assert.equal(result.ok, true);
  assert.equal(result.data.name, 'Widget');
});

test('description defaults to empty rather than being required', () => {
  const result = validate(productBody, { name: 'Widget', priceCents: 100 });
  assert.equal(result.ok, true);
  assert.equal(result.data.description, '');
});

test('an empty name is rejected with a field path', () => {
  const result = validate(productBody, { name: '   ', priceCents: 100 });
  assert.equal(result.ok, false);
  assert.equal(result.errors[0].path, 'name');
});

test('a negative or non-integer price is rejected', () => {
  assert.equal(validate(productBody, { name: 'W', priceCents: -1 }).ok, false);
  assert.equal(validate(productBody, { name: 'W', priceCents: 1.5 }).ok, false);
});

test('a price sent as a string is rejected, not coerced', () => {
  assert.equal(validate(productBody, { name: 'W', priceCents: '100' }).ok, false);
});

test('unknown keys are rejected rather than silently dropped', () => {
  const result = validate(productBody, { name: 'W', priceCents: 1, isAdmin: true });
  assert.equal(result.ok, false);
});

test('search requires a term and caps the limit', () => {
  assert.equal(validate(searchQuery, { q: '' }).ok, false);
  assert.equal(validate(searchQuery, { q: 'widget', limit: 500 }).ok, false);
  assert.equal(validate(searchQuery, { q: 'widget' }).data.limit, 25);
});

test('ids must be positive integers', () => {
  assert.equal(idParam.safeParse('12').success, true);
  assert.equal(idParam.safeParse('0').success, false);
  assert.equal(idParam.safeParse('abc').success, false);
});

