'use strict';

/** Integration tests: real HTTP requests through the assembled app, asserting response codes
 *  and cache hit/miss behaviour end to end. */

const assert = require('node:assert/strict');
const { test, beforeEach } = require('node:test');
const request = require('supertest');
const { createApp } = require('../../app');
const cache = require('../../cache');
const { db } = require('../../db');

const app = createApp();

beforeEach(() => {
  cache.reset();
  db.exec('DELETE FROM products');
});

async function create(body) {
  return request(app).post('/api/products').send(body);
}

test('POST creates a product and returns 201', async () => {
  const res = await create({ name: 'Widget', description: 'A small widget', priceCents: 500 });
  assert.equal(res.status, 201);
  assert.equal(res.body.name, 'Widget');
  assert.ok(res.body.id > 0);
});

test('POST with an invalid body returns 400 and does not create anything', async () => {
  const res = await create({ name: '', priceCents: -5 });
  assert.equal(res.status, 400);
  assert.ok(res.body.errors.length > 0);

  const search = await request(app).get('/api/products').query({ q: 'widget' });
  assert.equal(search.body.results.length, 0);
});

test('a repeated search is served from the cache', async () => {
  await create({ name: 'Widget', description: 'A small widget', priceCents: 500 });

  const first = await request(app).get('/api/products').query({ q: 'widget' });
  const second = await request(app).get('/api/products').query({ q: 'widget' });

  assert.equal(first.status, 200);
  assert.equal(first.headers['x-cache'], 'MISS');
  assert.equal(second.headers['x-cache'], 'HIT');
  assert.deepEqual(first.body.results, second.body.results);
});

test('creating a product invalidates cached searches', async () => {
  await create({ name: 'Widget', description: 'first', priceCents: 100 });
  await request(app).get('/api/products').query({ q: 'widget' }); // warms the cache

  await create({ name: 'Widget Two', description: 'second', priceCents: 200 });
  const after = await request(app).get('/api/products').query({ q: 'widget' });

  assert.equal(after.headers['x-cache'], 'MISS', 'the write must have evicted the search');
  assert.equal(after.body.results.length, 2);
});

test('updating a product invalidates its cached entry', async () => {
  const created = await create({ name: 'Widget', description: 'first', priceCents: 100 });
  const id = created.body.id;

  await request(app).get('/api/products/' + id);
  const updated = await request(app)
    .put('/api/products/' + id)
    .send({ name: 'Renamed', description: 'second', priceCents: 150 });
  assert.equal(updated.status, 200);

  const after = await request(app).get('/api/products/' + id);
  assert.equal(after.headers['x-cache'], 'MISS');
  assert.equal(after.body.name, 'Renamed');
});

test('an unknown product is 404 and an invalid id is 400', async () => {
  assert.equal((await request(app).get('/api/products/999999')).status, 404);
  assert.equal((await request(app).get('/api/products/abc')).status, 400);
});

test('a search term containing SQL is treated as text, not executed', async () => {
  await create({ name: 'Widget', description: 'A small widget', priceCents: 500 });

  const res = await request(app).get('/api/products').query({ q: "'; DROP TABLE products; --" });

  assert.equal(res.status, 200);
  assert.equal(res.body.results.length, 0);
  // The table is still there, which is the actual assertion.
  const still = await request(app).get('/api/products').query({ q: 'widget' });
  assert.equal(still.body.results.length, 1);
});

