'use strict';

/** Integration tests for the security middleware: headers, CORS, rate limiting, body size. */

const assert = require('node:assert/strict');
const { test } = require('node:test');
const request = require('supertest');
const { createApp, ALLOWED_ORIGINS } = require('../../app');

const app = createApp();

test('helmet sets the strict security headers on every response', async () => {
  const res = await request(app).get('/api/products').query({ q: 'anything' });

  assert.equal(res.headers['x-content-type-options'], 'nosniff');
  assert.equal(res.headers['referrer-policy'], 'no-referrer');
  assert.ok(res.headers['content-security-policy']);
  assert.ok(res.headers['strict-transport-security']);
  // helmet removes this one; its presence would advertise the stack.
  assert.equal(res.headers['x-powered-by'], undefined);
});

test('the content security policy forbids framing and plugins', async () => {
  const res = await request(app).get('/api/products').query({ q: 'x' });
  const csp = res.headers['content-security-policy'];

  assert.match(csp, /frame-ancestors 'none'/);
  assert.match(csp, /object-src 'none'/);
});

test('an allowed origin is echoed back', async () => {
  const res = await request(app)
    .get('/api/products')
    .query({ q: 'x' })
    .set('Origin', ALLOWED_ORIGINS[0]);

  assert.equal(res.headers['access-control-allow-origin'], ALLOWED_ORIGINS[0]);
});

test('an origin outside the allow-list is refused, not reflected', async () => {
  const res = await request(app)
    .get('/api/products')
    .query({ q: 'x' })
    .set('Origin', 'https://evil.example.com');

  assert.equal(res.headers['access-control-allow-origin'], undefined);
  assert.equal(res.status, 403);
});

test('a body over the limit is rejected before it is parsed', async () => {
  const res = await request(app)
    .post('/api/products')
    .send({ name: 'W', description: 'x'.repeat(40000), priceCents: 1 });

  assert.equal(res.status, 413);
});

test('the rate limiter advertises the remaining budget', async () => {
  const res = await request(app).get('/api/products').query({ q: 'x' });
  assert.ok(res.headers['ratelimit-remaining'] !== undefined);
});
